using Microsoft.EntityFrameworkCore;using Mbb.Archive.Modules.AccessControl.Application.Abstractions;using Mbb.Archive.Modules.AccessControl.Domain.Roles;namespace Mbb.Archive.Modules.AccessControl.Infrastructure.Persistence;internal sealed class EfAccessRepository:IAccessRepository,IPermissionChecker{private readonly AccessDbContext _db;public EfAccessRepository(AccessDbContext db){_db=db;}public async Task AddRoleAsync(Role role,CancellationToken ct)=>await _db.Roles.AddAsync(role,ct);public Task<Role?> GetRoleAsync(Guid id,CancellationToken ct)=>_db.Roles.Include(x=>x.Permissions).SingleOrDefaultAsync(x=>x.Id==id,ct);public Task<Role?> GetRoleByCodeAsync(string code,CancellationToken ct)=>_db.Roles.Include(x=>x.Permissions).SingleOrDefaultAsync(x=>x.Code==code,ct);public async Task AddUserRoleAsync(UserRole ur,CancellationToken ct)=>await _db.UserRoles.AddAsync(ur,ct);public Task<bool> HasPermissionAsync(string subjectId,IReadOnlyCollection<string> externalRoles,string permission,CancellationToken ct){var p=permission.ToLowerInvariant();return _db.Roles.AsNoTracking().Where(r=>r.Permissions.Any(x=>x.Permission==p)).AnyAsync(r=>externalRoles.Contains(r.Code)||_db.UserRoles.Any(ur=>ur.SubjectId==subjectId&&ur.RoleId==r.Id),ct);}public async Task<IReadOnlyList<string>> GetPermissionsAsync(string subjectId,IReadOnlyCollection<string> externalRoles,CancellationToken ct)
 =>await _db.Roles.AsNoTracking()
  .Where(r=>externalRoles.Contains(r.Code)||_db.UserRoles.Any(ur=>ur.SubjectId==subjectId&&ur.RoleId==r.Id))
  .SelectMany(r=>r.Permissions.Select(x=>x.Permission))
  .Distinct().OrderBy(x=>x).ToListAsync(ct);
 Task<bool> IPermissionChecker.HasPermissionAsync(string s,IReadOnlyCollection<string> r,string p,CancellationToken ct)=>HasPermissionAsync(s,r,p,ct);}
